#!/usr/bin/env bash
set -euo pipefail

# Fixes the whole page scrolling horizontally on mobile (Build-your-slab /
# gift-ready grid was letting its horizontal-scroll strip stretch the entire
# row past the viewport). One-line-per-card fix.
#
# Clones into an isolated, branch-named directory ("gowebsite-claude-home-horizontal-overflow-fix") so it can't
# collide with your Codespace's own checkout or leftovers from earlier runs.

REPO_URL="https://github.com/yoosuf0806/go-website.git"
BRANCH="claude/home-horizontal-overflow-fix"
DIR="gowebsite-claude-home-horizontal-overflow-fix"

if [ -d "$DIR" ]; then
  echo "$DIR already exists here (probably from a previous run of this exact script) — remove it first:" >&2
  echo "  rm -rf $DIR" >&2
  exit 1
fi

echo "Cloning fresh main into $DIR..."
git clone "$REPO_URL" "$DIR"
cd "$DIR"
git checkout -b "$BRANCH"

echo "Applying patch..."
base64 -d <<'PATCH_B64' | git am

PATCH_B64

echo
echo "Patch applied cleanly on branch $BRANCH in ./$DIR"
echo "Next steps:"
echo "  cd $DIR"
echo "  git push -u origin $BRANCH"
echo "  Open a PR: https://github.com/yoosuf0806/go-website/compare/main...$BRANCH"
